/**
 * Registers a handler for one event type. Call the return value to detach.
 *
 * Subscribing an already-attached handler is a no-op. The unsubscribe always
 * removes from the live set for the type, so it keeps working after later
 * subscribes. `emit()` iterates a snapshot, so mutating the set is safe.
 */
export function subscribe<K extends TaskflowEventType>(
  type: K,
  handler: EventHandler<K>,
): Unsubscribe {
  const fn = handler as EventHandler<TaskflowEventType>;
  let set = handlers.get(type);
  if (!set) {
    set = new Set();
    handlers.set(type, set);
  }
  set.add(fn);
  return () => {
    handlers.get(type)?.delete(fn);
  };
}

